const demoArtisans=[{name:'María del Carmen Vega',city:'Ciudad Eten, Lambayeque',specialty:'Tejidos y accesorios de algodón',bio:'Tejedora de tercera generación. Combino puntos tradicionales y colores modernos para crear bolsos, manteles y detalles para regalo. Realizo pedidos personalizados.',story:'Cada pieza lleva tiempo, cariño y la historia de las manos que me enseñaron a tejer.',experience:'12 años de experiencia',fair:'Ferias de emprendimiento en Lambayeque',avatar:'🧶',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''},{name:'Rosa Huamán',city:'Monsefú, Lambayeque',specialty:'Cestería y accesorios de fibra vegetal',bio:'Trabajo con fibras vegetales para confeccionar canastas, carteras y sombreros. Mi taller familiar apuesta por objetos útiles con una estética natural y acabados cuidadosos.',story:'Quiero que las nuevas generaciones conozcan el valor del trabajo artesanal.',experience:'9 años de experiencia',fair:'Exposiciones y ferias artesanales de Monsefú',avatar:'🪡',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''},{name:'Elena Pérez',city:'Mórrope, Lambayeque',specialty:'Cerámica y decoración artesanal',bio:'Elaboro piezas de cerámica decorativa inspiradas en formas y colores del entorno. Me gusta crear objetos para hogares y obsequios con una historia propia.',story:'La artesanía transforma materiales cotidianos en recuerdos especiales.',experience:'7 años de experiencia',fair:'Ferias culturales y encuentros de artistas locales',avatar:'🏺',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''}];
